-- Produs nou: topor multifuncțional camping 30 cm (livrat prin Helpship; stoc 0 până ajunge marfa la depozit)
INSERT OR IGNORE INTO products (slug, title, subtitle, description, price, compare_at_price, cost_price, sku, stock, track_stock, weight_g, images, benefits, faq, bundles, badge, category, active, featured, sort)
VALUES ('topor-multifunctional-camping', 'Topor multifuncțional camping, 30 cm', 'Cu fierăstrău și cârlig integrate, teacă de protecție inclusă',
 'Un topor compact, de doar 30 cm, gândit pentru camping, drumeții și treburile ușoare din grădină. Are lama din oțel cu finisaj negru, un mic fierăstrău pe spatele lamei și un cârlig util pentru tras sau ridicat.

Mânerul ergonomic are o textură antiderapantă care oferă o prindere sigură și control bun, chiar și cu mâinile ude sau cu mănuși.

Vine cu teacă de protecție, cu capsă de închidere și prindere pe curea. Lama stă acoperită când nu folosești toporul, iar el încape ușor în rucsac, în trusa de camping sau în portbagaj.',
 10000, 0, 3000, 'CHI-TOP-01', 0, 1, 700,
 '["/img/topor-camping-1.jpg", "/img/topor-camping-5.jpg", "/img/topor-camping-2.jpg", "/img/topor-camping-4.jpg", "/img/topor-camping-3.jpg"]', '["Compact: doar 30 cm, încape în rucsac sau portbagaj", "Lamă din oțel, cu fierăstrău și cârlig integrate", "Mâner ergonomic cu textură antiderapantă", "Teacă de protecție inclusă, cu prindere pe curea"]', '[{"q": "Ce primesc în colet?", "a": "Toporul de 30 cm și teaca de protecție pentru lamă, cu capsă de închidere."}, {"q": "Pentru ce îl pot folosi?", "a": "Pentru camping, drumeții, pescuit, picnic și treburi ușoare în grădină sau în gospodărie: crengi, țăruși, lemne mici pentru foc."}, {"q": "Pot despica lemne mari cu el?", "a": "Nu este gândit pentru asta. Fiind un topor compact, de 30 cm, e potrivit pentru lemne mici și crengi. Pentru buşteni mari ai nevoie de un topor mare."}, {"q": "Cum îl transport în siguranță?", "a": "Pui lama în teaca inclusă și o închizi cu capsa. Teaca se poate prinde de curea sau de rucsac."}, {"q": "Este potrivit pentru copii?", "a": "Nu. Toporul are lamă ascuțită și este destinat adulților. Păstrează-l în teacă, departe de copii."}, {"q": "Cât durează livrarea?", "a": "24–48 de ore lucrătoare de la confirmarea comenzii. Plătești la livrare."}]', '[{"qty": 1, "pct": 0, "label": ""}, {"qty": 2, "pct": 10, "label": "Cel mai ales"}, {"qty": 3, "pct": 15, "label": "Cea mai bună ofertă"}]', 'Nou', 'Outdoor', 1, 0, 3);
UPDATE products SET sections = '[{"title": "Mai mult decât un topor", "image": "/img/topor-camping-5.jpg", "text": "Pe lângă lama principală, toporul are un fierăstrău pe spatele lamei, pentru crengi și lemn subțire, și un cârlig util pentru tras sau ridicat.\n\nAstfel ai mai multe unelte într-una singură, fără greutate în plus în rucsac."}, {"title": "Prindere sigură, control bun", "image": "/img/topor-camping-4.jpg", "text": "Mânerul are o formă ergonomică și o textură antiderapantă, ca să stea ferm în mână la fiecare lovitură.\n\nLama din oțel cu finisaj negru e gândită pentru folosire repetată în aer liber."}, {"title": "Mic, dar gata de drum", "image": "/img/topor-camping-2.jpg", "text": "Cu o lungime totală de 30 cm, toporul încape în rucsac, în trusa de camping sau în portbagaj, fără să ocupe mult loc.\n\nE potrivit pentru camping, drumeții, pescuit, picnic sau grădină."}, {"title": "Teacă de protecție inclusă", "image": "/img/topor-camping-3.jpg", "text": "Toporul vine cu o teacă pentru lamă, care se închide cu capsă. Lama stă acoperită când nu o folosești, iar transportul e mult mai sigur.\n\nTeaca se poate prinde de curea sau de rucsac."}]', specs = '[{"k": "Tip", "v": "Topor multifuncțional pentru camping și outdoor"}, {"k": "Lungime totală", "v": "30 cm"}, {"k": "Lamă", "v": "Oțel cu finisaj negru"}, {"k": "Funcții", "v": "Topor, fierăstrău pe spatele lamei, cârlig"}, {"k": "Mâner", "v": "Ergonomic, cu textură antiderapantă"}, {"k": "Culoare", "v": "Negru cu portocaliu"}, {"k": "Include", "v": "Topor și teacă de protecție cu capsă"}, {"k": "Recomandat pentru", "v": "Camping, drumeții, pescuit, grădină, portbagaj auto"}, {"k": "Atenție", "v": "Lamă ascuțită. Nu este destinat copiilor."}]', fulfillment = 'helpship', length_cm = 33, width_cm = 18, height_cm = 5
WHERE slug = 'topor-multifunctional-camping';
